ALPHABET = ('0123456789abcdefghijklmnopqrstuvwxyz'
            'ABCDEFGHIJKLMNOPQRSTUVWXYZ')  # 62자

def encode(n):  # DB 일련번호 → 짧은 코드 (62진수)
    if n == 0:
        return ALPHABET[0]
    code = ''
    while n > 0:
        n, r = divmod(n, 62)
        code = ALPHABET[r] + code
    return code

def shorten(long_url, db):
    new_id = db.insert(long_url)  # 자동 증가 ID
    return 'https://sho.rt/' + encode(new_id)

def resolve(code, db):
    n = 0
    for ch in code:  # 62진수 → 10진수
        n = n * 62 + ALPHABET.index(ch)
    return db.get(n)  # 301/302 리다이렉트 대상

# encode(10**9) → '15FTGg' (6자로 10억 개 표현)
